"""Read-only sync orchestration and deliberately minimal local sync status."""

from __future__ import annotations

from datetime import UTC, datetime
from typing import Any
from sqlalchemy.orm import Session

from ..config import Settings
from ..integrations.graph import GraphClient
from .crypto import EncryptedTokenStore, TokenStoreError
from .graph import fetch_signals, persist_signals
from .promotion import promote_signals
from .sync_registry import UnknownSourceKindError, get_sync_handler, register_sync_handler

GRAPH_SOURCE_KIND = "graph"


class SyncError(RuntimeError):
    pass


def token_store(settings: Settings) -> EncryptedTokenStore:
    key = settings.app_encryption_key
    if key is None:
        raise SyncError("APP_ENCRYPTION_KEY is not configured")
    return EncryptedTokenStore(settings.token_store_path, key.get_secret_value())


def status(settings: Settings) -> dict[str, Any]:
    configured = not settings.graph_configuration_errors()
    try:
        connected = token_store(settings).load() is not None
    except (SyncError, TokenStoreError):
        connected = False
    return {"configured": configured, "connected": connected, "mode": "read-only", "last_sync_at": None}


def _owner_addresses(profile: dict[str, Any]) -> tuple[str, ...]:
    """Both addresses Graph knows the signed-in user by; alias-domain tenants differ in the two."""
    return tuple(address for address in (profile.get("userPrincipalName"), profile.get("mail")) if isinstance(address, str))


def _sync_graph(settings: Settings, db: Session | None = None, limit: int = 50, client: GraphClient | None = None, **_: Any) -> dict[str, Any]:
    """The only handler that knows about Microsoft Graph; the identity assertion
    below is Graph-specific and must not apply to any other registered kind."""
    if settings.graph_configuration_errors():
        raise SyncError("Microsoft Graph is not configured")
    try:
        token = token_store(settings).load()
    except TokenStoreError as error:
        raise SyncError("Stored Graph credentials are unavailable") from error
    if not token or not isinstance(token.get("access_token"), str):
        raise SyncError("Microsoft Graph is not connected")
    graph = client or GraphClient(token["access_token"])
    profile = graph.me()
    if profile.get("id") != settings.microsoft_target_user_id:
        raise SyncError("connected Microsoft user does not match MICROSOFT_TARGET_USER_ID")
    signals = fetch_signals(graph, limit)
    created = persist_signals(db, signals) if db is not None else 0
    # Every signal is kept as a ``Source``; only the actionable ones reach the queue.
    promoted = promote_signals(db, signals, _owner_addresses(profile)) if db is not None else 0
    return {"mode": "read-only", "synced_at": datetime.now(UTC).isoformat(), "count": len(signals), "new_sources": created, "new_work_items": promoted}


register_sync_handler(GRAPH_SOURCE_KIND, _sync_graph)


def sync(settings: Settings, db: Session | None = None, client: GraphClient | None = None, limit: int = 50, kind: str = GRAPH_SOURCE_KIND) -> dict[str, Any]:
    """Dispatch to whatever handler is registered for ``kind``.

    Adding a new source kind (Jira, Freshservice, ...) means registering a
    handler for it elsewhere -- nothing here has to change.
    """
    try:
        handler = get_sync_handler(kind)
    except UnknownSourceKindError as error:
        raise SyncError(str(error)) from error
    return handler(settings, db=db, limit=limit, client=client)

"""Normalization boundary between raw Graph responses and local agent intake."""

from __future__ import annotations

from typing import Any
from datetime import datetime

from sqlalchemy import select
from sqlalchemy.orm import Session

from ..integrations.graph import GraphClient
from ..models import Source, SourceKind, SourceSignalContext


def _heuristic_headers(headers: Any) -> dict[str, str]:
    """Only the headers ``should_promote`` reads, so nothing else is kept on disk.

    Graph returns the whole ``internetMessageHeaders`` block -- routing chains,
    authentication results, the subject line again, tenant bookkeeping -- and none of
    it is an input to any rule. ``HEURISTIC_HEADERS`` is imported here rather than at
    module scope because ``promotion`` imports ``parse_observed_at`` from this module.
    """
    from .promotion import HEURISTIC_HEADERS

    return {str(name): str(value) for name, value in dict(headers or {}).items()
            if str(name).lower() in HEURISTIC_HEADERS}


def parse_observed_at(value: Any) -> datetime:
    """Graph's ISO-8601 timestamp, or now if it is missing or unparseable."""
    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00")) if value else datetime.now()
    except ValueError:
        return datetime.now()


def _address(entry: Any) -> str | None:
    """The plain address inside a Graph ``emailAddress`` wrapper, if there is one."""
    email_address = entry.get("emailAddress") if isinstance(entry, dict) else None
    address = email_address.get("address") if isinstance(email_address, dict) else None
    return str(address) if address else None


def _addresses(entries: Any) -> list[str]:
    return [address for entry in entries if (address := _address(entry))] if isinstance(entries, list) else []


def _headers(entries: Any) -> dict[str, str]:
    """Internet message headers as a name-keyed mapping; promotion reads bulk markers from it."""
    if not isinstance(entries, list):
        return {}
    return {str(entry["name"]): str(entry.get("value") or "") for entry in entries
            if isinstance(entry, dict) and entry.get("name")}


def _teams_sender_kind(row: dict[str, Any]) -> str:
    """Whether an application or a person posted a Teams message."""
    origin = row.get("from") if isinstance(row.get("from"), dict) else {}
    return "application" if origin.get("application") else "user"


def normalize_email(row: dict[str, Any]) -> dict[str, Any]:
    return {"external_id": f"outlook:{row['id']}", "source_kind": "outlook_email", "title": row.get("subject") or "(no subject)", "excerpt": row.get("bodyPreview") or "", "source_url": row.get("webLink"), "observed_at": row.get("receivedDateTime"),
            "sender": _address(row.get("from")), "sender_kind": "user", "to_recipients": _addresses(row.get("toRecipients")), "headers": _headers(row.get("internetMessageHeaders"))}


def normalize_teams(row: dict[str, Any]) -> dict[str, Any]:
    body = row.get("body") or {}
    # A Teams ``from.user`` is an identity (id, displayName) with no address, so
    # there is no sender to hand the automated-sender rule; only the kind is known.
    return {"external_id": f"teams:{row['id']}", "source_kind": "teams_message", "title": row.get("chatTopic") or "Teams conversation", "excerpt": body.get("content") if isinstance(body, dict) else str(body), "source_url": row.get("webUrl"), "observed_at": row.get("createdDateTime"),
            "sender": None, "sender_kind": _teams_sender_kind(row), "to_recipients": [], "headers": {}}


def fetch_signals(client: GraphClient, limit: int = 50) -> list[dict[str, Any]]:
    rows = [*(normalize_email(row) for row in client.inbox_messages(limit)), *(normalize_teams(row) for row in client.chat_messages(limit))]
    deduped: dict[str, dict[str, Any]] = {}
    for row in rows:
        deduped.setdefault(row["external_id"], row)
    return list(deduped.values())


def persist_signals(db: Session, signals: list[dict[str, Any]]) -> int:
    """Store bounded source metadata idempotently; never persist Graph tokens."""
    created = 0
    for signal in signals:
        external_id = str(signal["external_id"])
        if db.scalar(select(Source.id).where(Source.external_id == external_id)) is not None:
            continue
        parsed_time = parse_observed_at(signal.get("observed_at"))
        kind = SourceKind(str(signal["source_kind"]))
        source = Source(
            kind=kind,
            external_id=external_id,
            subject=str(signal.get("title") or "")[:500] or None,
            url=str(signal.get("source_url") or "")[:2048] or None,
            excerpt=str(signal.get("excerpt") or "")[:2_000] or None,
            observed_at=parsed_time,
        )
        # Carried across so a labeled-sample export can rebuild the exact signal
        # shape ``should_promote`` decided from -- otherwise a sample read back
        # from the database could only ever hit the heuristic's default rule.
        # Headers are narrowed to the ones a rule reads: that is the whole reason
        # they are stored, and the rest of the block is content-bearing metadata.
        source.signal_context = SourceSignalContext(
            sender=str(signal["sender"])[:320] if signal.get("sender") else None,
            sender_kind=str(signal.get("sender_kind") or "") or None,
            to_recipients=list(signal.get("to_recipients") or []) or None,
            headers=_heuristic_headers(signal.get("headers")) or None,
        )
        db.add(source)
        created += 1
    db.commit()
    return created

from uuid import UUID

from fastapi import HTTPException, status
from sqlalchemy import select
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session, selectinload

from ..models import AgentDispatch, DispatchStatus, Source, WorkEvidence, WorkItem, WorkStatus
from ..schemas import (AgentDispatchRequest, AgentDispatchUpdate, EvidenceInput, SourceCreate, SourceUpdate,
                       WorkItemCreate, WorkItemUpdate)


def not_found(entity: str) -> HTTPException:
    return HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=f"{entity} not found")


def conflict(detail: str) -> HTTPException:
    return HTTPException(status_code=status.HTTP_409_CONFLICT, detail=detail)


def get_work_item(db: Session, item_id: UUID) -> WorkItem:
    item = db.scalar(select(WorkItem).options(selectinload(WorkItem.evidence)).where(WorkItem.id == item_id))
    if item is None:
        raise not_found("Work item")
    return item


def list_work_items(db: Session, status_filter: WorkStatus | None, source_kind: str | None, assigned_agent: str | None) -> list[WorkItem]:
    query = select(WorkItem).options(selectinload(WorkItem.evidence)).order_by(WorkItem.updated_at.desc())
    if status_filter:
        query = query.where(WorkItem.status == status_filter)
    if source_kind:
        query = query.where(WorkItem.source_kind == source_kind)
    if assigned_agent:
        query = query.where(WorkItem.assigned_agent == assigned_agent)
    return list(db.scalars(query))


def create_work_item(db: Session, payload: WorkItemCreate) -> WorkItem:
    data = payload.model_dump(exclude={"evidence"}, mode="json")
    data["source_url"] = str(data["source_url"]) if data.get("source_url") else None
    item = WorkItem(**data)
    for evidence in payload.evidence:
        item.evidence.append(WorkEvidence(**evidence.model_dump(exclude={"observed_at"}), observed_at=evidence.observed_at))
    db.add(item)
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
        raise conflict("A work item with this source_external_id already exists")
    return get_work_item(db, item.id)


def update_work_item(db: Session, item_id: UUID, payload: WorkItemUpdate) -> WorkItem:
    item = get_work_item(db, item_id)
    for key, value in payload.model_dump(exclude_unset=True).items():
        setattr(item, key, value)
    db.commit()
    return get_work_item(db, item.id)


def delete_work_item(db: Session, item_id: UUID) -> None:
    db.delete(get_work_item(db, item_id))
    db.commit()


def add_evidence(db: Session, item_id: UUID, payload: EvidenceInput) -> WorkEvidence:
    item = get_work_item(db, item_id)
    evidence = WorkEvidence(
        work_item_id=item.id,
        **payload.model_dump(exclude={"observed_at"}),
        observed_at=payload.observed_at,
    )
    db.add(evidence)
    db.commit()
    db.refresh(evidence)
    return evidence


def delete_evidence(db: Session, item_id: UUID, evidence_id: UUID) -> None:
    get_work_item(db, item_id)
    evidence = db.get(WorkEvidence, evidence_id)
    if evidence is None or evidence.work_item_id != item_id:
        raise not_found("Evidence")
    db.delete(evidence)
    db.commit()


def get_source(db: Session, source_id: UUID) -> Source:
    source = db.get(Source, source_id)
    if source is None:
        raise not_found("Source")
    return source


def create_source(db: Session, payload: SourceCreate) -> Source:
    data = payload.model_dump(mode="json")
    data["url"] = str(data["url"]) if data.get("url") else None
    source = Source(**data)
    db.add(source)
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
        raise conflict("A source with this external_id already exists")
    return get_source(db, source.id)


def update_source(db: Session, source_id: UUID, payload: SourceUpdate) -> Source:
    source = get_source(db, source_id)
    data = payload.model_dump(exclude_unset=True, mode="json")
    if "url" in data:
        data["url"] = str(data["url"]) if data["url"] else None
    for key, value in data.items():
        setattr(source, key, value)
    db.commit()
    return get_source(db, source_id)


def delete_source(db: Session, source_id: UUID) -> None:
    db.delete(get_source(db, source_id))
    db.commit()


def create_dispatch(db: Session, payload: AgentDispatchRequest) -> AgentDispatch:
    get_work_item(db, payload.work_item_id)
    dispatch = AgentDispatch(**payload.model_dump())
    db.add(dispatch)
    db.commit()
    db.refresh(dispatch)
    return dispatch


def update_dispatch(db: Session, dispatch_id: UUID, payload: AgentDispatchUpdate) -> AgentDispatch:
    dispatch = db.get(AgentDispatch, dispatch_id)
    if dispatch is None:
        raise not_found("Agent dispatch")
    dispatch.status = payload.status
    if payload.result is not None:
        dispatch.result = payload.result
    db.commit()
    db.refresh(dispatch)
    return dispatch


def list_dispatches(db: Session, work_item_id: UUID | None = None) -> list[AgentDispatch]:
    query = select(AgentDispatch).order_by(AgentDispatch.created_at.desc())
    if work_item_id:
        query = query.where(AgentDispatch.work_item_id == work_item_id)
    return list(db.scalars(query))

